"""Full taxonomy/catalog and associated declaration readings."""
import json,pathlib
H=pathlib.Path(__file__).resolve().parent;P='additional_pfp_infrastructure_remaining';p=H/(P+'_notes.json');n=json.loads(p.read_text())
common=' Registry membership is vocabulary admission, not execution or proof of the named property. Mutable registration can diverge from import-time Enum/VALID snapshots; row errors are silently skipped and fallback behavior is not evidence of canonical resource health.'
